class Solution {
public:
    ListNode* frequenciesOfElements(ListNode* head) {
        unordered_map<int, int> count;
        for (auto p = head; p; p = p->next) ++count[p->val];
        ListNode dummy(0), *tail = &dummy;
        for (auto& p : count) { tail->next = new ListNode(p.second); tail = tail->next; }
        return dummy.next;
    }
};
